int get_bt_socket_name(struct socket *sock, struct sockaddr *addr, int *addr_len, int peer) {
    struct sockaddr_hci *hci_addr = (struct sockaddr_hci *)addr;
    struct sock *sk = sock->sk;

    if (!sk || !hci_addr || !addr_len) {
        return -EBADFD;
    }

    if (peer) {
        if (sk->sk_state != BT_CONNECTED) {
            return -EBADFD;
        }
    }

    lock_sock(sk);

    hci_addr->hci_family = AF_BLUETOOTH;
    hci_addr->hci_dev = sk->sk_dev;
    hci_addr->hci_channel = sk->sk_channel;

    release_sock(sk);

    *addr_len = sizeof(struct sockaddr_hci);

    return 0;
}
